def card(im,code):
    im=im.convert('RGB')
    bbox=ImageChops.difference(im,Image.new('RGB',im.size,'white')).getbbox()
    cut=im.crop(bbox); cut.thumbnail((258,263),Image.Resampling.LANCZOS)
    out=Image.new('RGB',(266,298),'white')
    out.paste(cut,((266-cut.width)//2,28+(263-cut.height)//2))
    dr=ImageDraw.Draw(out)
    dr.text((10,3),code,fill='#141414',font=ImageFont.load_default(size=20))
    return out

def main(source):
    assert sha256(source.read_bytes()).hexdigest()==SHA
    im=Image.open(source).convert('RGB')
    assert im.size==(2802,3697)
    imgs={}
    for n,paths in CONTOURS.items():
        mask=Image.new('L',im.size);draw=ImageDraw.Draw(mask)
        for poly in paths:
            draw.polygon([(2*x,2*y) for x,y in poly],fill=255)
        # Donner du jeu aux pointes fines. Le tampon conserve la couleur du
        # parchemin jusque dans les derniers millimètres de chaque dessin.
        box=mask.getbbox()
        box=(box[0]-15,box[1]-15,box[2]+15,box[3]+15)
        region=im.crop(box)
        alpha=mask.crop(box).filter(ImageFilter.MaxFilter(25)).filter(ImageFilter.GaussianBlur(1.4))
        imgs[n]=Image.composite(region,Image.new('RGB',region.size,(205,184,157)),alpha)
    models={}
    for i in (4,5):
        original=Image.open(HERE/f'modele-{i}.png')
        models[i]=original.crop((20,20,original.width-20,original.height-66))
    keys={}
    for tag,seed in [('nacre',886099),('silex',998805)]:
        rng=random.Random(seed); pool=list(range(95,103));rng.shuffle(pool)
        pair=list(models);rng.shuffle(pair)
        key=dict(zip('XY',pair));key.update(zip('ABCDEFGH',pool)); keys[tag]=key
        sheet=Image.new('RGB',(1064,894),'white')
        for i,c in enumerate('XY'):
            sheet.paste(card(models[key[c]],c),(266+i*266,0))
        for i,c in enumerate('ABCDEFGH'):
            sheet.paste(card(imgs[key[c]],c),((i%4)*266,298+298*(i//4)))
        sheet.save(HERE/f'{tag}.jpg',quality=94)
    (HERE/'cle.json').write_text(json.dumps(keys,indent=2)+'\n')

if __name__=='__main__': main(Path(sys.argv[1]))
